{
  "name": "EPICS仪器服务器",
  "name_en": "EPICS Instrument Server",
  "manufacturer": "",
  "description": "这是一个用于实验室控制系统的EPICS仪器服务组件，用于连接仪器数据库并发布或更新仪器名称、位置名称、运动状态、信息消息和时间戳等过程变量。它更像是实验自动化系统中的控制服务，而不是独立的物理仪器。",
  "description_en": "This is an EPICS-based laboratory instrument service component that attaches to an instrument database and publishes or updates process variables such as instrument name, position name, motion state, info messages, and timestamps. It is better described as a control service within a lab automation system rather than a standalone physical instrument.",
  "actions": [
    {
      "action_name": "auto-MoveDone",
      "description": "标记移动已完成。",
      "description_en": "Mark motion as completed."
    },
    {
      "action_name": "auto-OnMove",
      "description": "处理或更新移动事件。",
      "description_en": "Handle or update a move event."
    },
    {
      "action_name": "auto-OnPosName",
      "description": "更新位置名称。",
      "description_en": "Update the position name."
    },
    {
      "action_name": "auto-OnInstName",
      "description": "更新仪器名称。",
      "description_en": "Update the instrument name."
    },
    {
      "action_name": "auto-SetTimeStamp",
      "description": "设置时间戳。",
      "description_en": "Set the timestamp."
    },
    {
      "action_name": "auto-SetInfo",
      "description": "设置信息消息。",
      "description_en": "Set the information message."
    },
    {
      "action_name": "auto-Start",
      "description": "启动仪器服务并记录启动信息。",
      "description_en": "Start the instrument service and record a startup message."
    },
    {
      "action_name": "auto-Shutdown",
      "description": "关闭仪器服务。",
      "description_en": "Shut down the instrument service."
    }
  ],
  "tag_hints": [
    "EPICS",
    "instrument database",
    "process variables",
    "lab automation",
    "control system",
    "IOC service"
  ]
}

